def transform(grid):
    out = [row[:] for row in grid]
    rows = len(grid)
    cols = len(grid[0])
    cells = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 2]
    top = min(r for r, c in cells)
    bottom = max(r for r, c in cells)
    left = min(c for r, c in cells)
    right = max(c for r, c in cells)

    # Extend the rectangle along each axis, away from any marker on that line.
    for r in range(top, bottom + 1):
        blocked_left = any(grid[r][c] not in (0, 2) for c in range(left))
        blocked_right = any(grid[r][c] not in (0, 2) for c in range(right + 1, cols))
        if not blocked_left:
            for c in range(left):
                if out[r][c] == 0:
                    out[r][c] = 2
        if not blocked_right:
            for c in range(right + 1, cols):
                if out[r][c] == 0:
                    out[r][c] = 2

    for c in range(left, right + 1):
        blocked_up = any(grid[r][c] not in (0, 2) for r in range(top))
        blocked_down = any(grid[r][c] not in (0, 2) for r in range(bottom + 1, rows))
        if not blocked_up:
            for r in range(top):
                if out[r][c] == 0:
                    out[r][c] = 2
        if not blocked_down:
            for r in range(bottom + 1, rows):
                if out[r][c] == 0:
                    out[r][c] = 2
    return out
